css:
.cosecha-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a2f25;
    background: linear-gradient(170deg, #fbf6ee 0%, #f6ecdc 55%, #f1e4cf 100%);
    border-radius: 18px;
}

.cosecha-container * {
    box-sizing: border-box;
}

.cosecha-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #5c3a1e 0%, #97551f 52%, #c2871f 100%);
    color: #fdf6ea;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(92, 58, 30, 0.32);
}

.cosecha-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.cosecha-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe2a6;
    background: rgba(255, 226, 166, 0.15);
    border: 1px solid rgba(255, 226, 166, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.cosecha-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f3e3c8;
}

.cosecha-venture {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.cosecha-vfact {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(92, 58, 30, 0.10);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.cosecha-vfact-cash { border-left: 5px solid #3f7d3a; }
.cosecha-vfact-bar { border-left: 5px solid #c2871f; }

.cosecha-vfact-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #5c3a1e;
}

.cosecha-vfact-cash .cosecha-vfact-name { color: #2f6b2c; }
.cosecha-vfact-bar .cosecha-vfact-name { color: #a06916; }

.cosecha-vfact-meta {
    font-size: 0.82rem;
    color: #7a6a56;
    line-height: 1.4;
}

.cosecha-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5a44;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.cosecha-period-counter #currentDay,
.cosecha-period-counter #maxPeriods {
    font-weight: 800;
    color: #3f7d3a;
}

.cosecha-round-name {
    background: rgba(63, 125, 58, 0.14);
    color: #2f6b2c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cosecha-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a06916;
    background: rgba(194, 135, 31, 0.14);
    border: 1px solid rgba(194, 135, 31, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.cosecha-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cosecha-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(92, 58, 30, 0.10);
    border-top: 4px solid #97551f;
}

.cosecha-card-runway { border-top-color: #c2871f; }
.cosecha-card-mrr { border-top-color: #3f7d3a; }
.cosecha-card-farmers { border-top-color: #2f6b6b; }
.cosecha-card-survival { border-top-color: #7d4fa0; }

.cosecha-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7860;
}

.cosecha-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #5c3a1e;
    font-variant-numeric: tabular-nums;
}

.cosecha-card-runway .cosecha-value { color: #c2871f; }
.cosecha-card-mrr .cosecha-value { color: #3f7d3a; }
.cosecha-card-farmers .cosecha-value { color: #2f6b6b; }
.cosecha-card-survival .cosecha-value { color: #7d4fa0; }

.cosecha-sublabel {
    font-size: 0.76rem;
    color: #9a8870;
    line-height: 1.35;
}

/* Runway danger / safe states */
.cosecha-card-runway.cosecha-runway-danger { border-top-color: #c0392b; }
.cosecha-card-runway.cosecha-runway-danger .cosecha-value { color: #c0392b; }
.cosecha-card-runway.cosecha-runway-good { border-top-color: #3f7d3a; }
.cosecha-card-runway.cosecha-runway-good .cosecha-value { color: #3f7d3a; }

/* Survival colour states */
.cosecha-card-survival.cosecha-survival-low .cosecha-value { color: #c0392b; }
.cosecha-card-survival.cosecha-survival-mid .cosecha-value { color: #c2871f; }
.cosecha-card-survival.cosecha-survival-high .cosecha-value { color: #3f7d3a; }

.cosecha-unit-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #ecdfca;
    color: #6b5a44;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cosecha-unit-bar #unitDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
}

.cosecha-unit-bar.cosecha-unit-good #unitDisplay { color: #3f7d3a; }
.cosecha-unit-bar.cosecha-unit-mid #unitDisplay { color: #c2871f; }

.cosecha-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #3f7d3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(92, 58, 30, 0.08);
}

.cosecha-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cosecha-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #5c3a1e;
    margin-bottom: 6px;
}

.cosecha-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4d3f30;
}

.cosecha-briefing-text strong { color: #2f6b2c; }
.cosecha-briefing-text em { color: #a06916; font-style: italic; }

.cosecha-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(92, 58, 30, 0.08);
}

.cosecha-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #5c3a1e;
    border-bottom: 2px solid #f0e6d5;
    padding-bottom: 8px;
}

.cosecha-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3a29;
    margin: 14px 0 6px;
}

.cosecha-panel label[data-i18n="r3_shock_intro"] {
    background: rgba(192, 57, 43, 0.08);
    border-left: 4px solid #c0392b;
    color: #8a3326;
    padding: 10px 12px;
    border-radius: 8px;
    font-weight: 700;
}

.cosecha-container select,
.cosecha-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #dcc9a8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #3a2f25;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cosecha-container select:focus,
.cosecha-container input[type="number"]:focus {
    outline: none;
    border-color: #3f7d3a;
    box-shadow: 0 0 0 3px rgba(63, 125, 58, 0.16);
}

.cosecha-container select option {
    background-color: #fffdf8;
    color: #3a2f25;
}

.cosecha-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #3f7d3a;
}

.cosecha-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5a44;
    margin-top: 4px;
}

.cosecha-range-readout span:nth-child(2) {
    color: #3f7d3a;
    font-weight: 800;
}

.cosecha-hint {
    font-size: 0.8rem;
    color: #9a8870;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.cosecha-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cosecha-container .btn-primary {
    background: linear-gradient(135deg, #2f6b2c 0%, #3f7d3a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 107, 44, 0.30);
}

.cosecha-container .btn-primary:hover {
    filter: brightness(1.07);
}

.cosecha-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #dcc9a8;
    color: #7a6a56;
    background: transparent;
}

.cosecha-coach {
    background: linear-gradient(160deg, #5c3a1e 0%, #6e451f 100%);
    color: #f6e9d3;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(92, 58, 30, 0.26);
}

.cosecha-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffe2a6;
    margin-bottom: 8px;
}

.cosecha-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cosecha-coach-body strong { color: #9fd68f; }
.cosecha-coach-body em { color: #ffe2a6; font-style: italic; }

.cosecha-history,
.cosecha-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(92, 58, 30, 0.08);
}

.cosecha-history h3,
.cosecha-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #5c3a1e;
}

.cosecha-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4d3f30;
}

.cosecha-container table#usfHistoryTable th {
    background: #f4ecdd;
    color: #97551f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e6d6bd;
}

.cosecha-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1e8d9;
    color: #4d3f30;
}

.cosecha-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ee;
}

.cosecha-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cosecha-container {
        padding: 14px;
    }
    .cosecha-header h1 {
        font-size: 1.7rem;
    }
    .cosecha-venture {
        flex-direction: column;
    }
    .cosecha-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cosecha-value {
        font-size: 2rem;
    }
    .cosecha-clock {
        margin-left: 0;
    }
    .cosecha-period-counter {
        font-size: 0.88rem;
    }
    .cosecha-unit-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cosecha-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / investor-debrief scorecard (append-only, namespaced) ===== */
.lp-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.lp-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.lp-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.lp-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.lp-cm-score strong { color: #4f9bd9; }
.lp-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.lp-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.lp-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.lp-cm-target.lp-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.lp-cm-target.lp-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.lp-cm-tick { font-weight: 700; }
.lp-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.lp-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.lp-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.lp-cm-metric strong { font-size: 16px; color: #eceff6; }
.lp-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.lp-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .lp-cm-metric { min-width: 70px; } .lp-cm-verdict { font-size: 19px; } }

