(function() {
    'use strict';

    class LaunchPeruAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Launch Peru`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card — Cosecha Pay S.A.C. (PEN).
            this.START_CASH = 600000;     // S/ 600,000 in the bank
            this.START_BURN = 95000;      // S/ 95,000 net monthly burn
            this.START_MRR = 48000;       // S/ 48,000 monthly revenue
            this.START_FARMERS = 310;     // transacting farmers
            this.REGISTERED = 3200;       // vanity registrations
            this.START_ARPU = 155;        // S/ 155 / farmer / month
            this.MARGIN = 0.60;           // 60% contribution margin
            this.START_CAC = 220;         // S/ 220 per transacting farmer
            this.START_CHURN = 0.08;      // 8% monthly churn

            this.BAR_MRR = 150000;        // investor bar: S/ 150,000 MRR
            this.BAR_FARMERS = 1000;      // investor bar: 1,000 transacting farmers

            // Concept "true" answers (the survival path).
            this.TRUE_RISK = `activation`;
            this.TRUE_MARKET = `ica`;
            this.TRUE_FUNDING = `equity`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: this.START_CASH,
                    burn: this.START_BURN,
                    mrr: this.START_MRR,
                    farmers: this.START_FARMERS,
                    arpu: this.START_ARPU,
                    margin: this.MARGIN,
                    cac: this.START_CAC,
                    churn: this.START_CHURN,
                    runway: Math.round((this.START_CASH / this.START_BURN) * 10) / 10,
                    ltvCac: 0,            // computed below / each round
                    survival: 0,          // survival probability (%), set after round 1
                    // strategy flags for the debrief / hints
                    growthFirst: false,   // hired growth lead before credit-risk
                    creditHired: false,
                    spreadThin: false,    // entered more than one market
                    tookDebt: false,      // revenue-based debt at high burn
                    gamedMilestone: false,// discounted ARPU to chase the count
                    focused: false,       // won a single market
                    reserve: 0,           // S/ reserve held against the shock
                    // history arrays for the chart
                    runwayHistory: [Math.round((this.START_CASH / this.START_BURN) * 10) / 10],
                    mrrHistory: [this.START_MRR],
                    farmersHistory: [this.START_FARMERS],
                    survivalHistory: [40],
                    lastCoach: ``
                };
                // Seed an opening LTV:CAC and survival estimate.
                state.domainState.ltvCac = this._ltvCac(state.domainState);
                state.domainState.survival = 40;
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors so a blind
                // click-through does NOT auto-win.
                state.decisions = {
                    risk: `registrations`,
                    metric: `registered`,
                    diagnosis: `optimistic`,
                    focus: 30,
                    market: `all`,
                    funding: `rbf`,
                    hire1: `growth`,
                    hire2: `growth`,
                    burn: `none`,
                    competitor: `pricewar`,
                    credit: `ignore`,
                    reserve: 0,
                    pitch: `vanity`,
                    ask: `maxraise`,
                    defense: `luck`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ri = document.getElementById(`riskInput`);
                const me = document.getElementById(`metricInput`);
                const di = document.getElementById(`diagnosisInput`);
                const fo = document.getElementById(`focusInput`);
                if (ri) decisions.risk = ri.value;
                if (me) decisions.metric = me.value;
                if (di) decisions.diagnosis = di.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const ma = document.getElementById(`marketInput`);
                const fu = document.getElementById(`fundingInput`);
                const h1 = document.getElementById(`hire1Input`);
                const h2 = document.getElementById(`hire2Input`);
                if (ma) decisions.market = ma.value;
                if (fu) decisions.funding = fu.value;
                if (h1) decisions.hire1 = h1.value;
                if (h2) decisions.hire2 = h2.value;
                if (!decisions.market || !decisions.funding) { warn(`warn_choose`); return false; }
                if (decisions.hire1 === decisions.hire2) { warn(`warn_same_hire`); return false; }
            } else if (round === 3) {
                const bu = document.getElementById(`burnInput`);
                const co = document.getElementById(`competitorInput`);
                const cr = document.getElementById(`creditInput`);
                const re = document.getElementById(`reserveInput`);
                if (bu) decisions.burn = bu.value;
                if (co) decisions.competitor = co.value;
                if (cr) decisions.credit = cr.value;
                if (re) decisions.reserve = parseFloat(re.value);
                if (!Number.isFinite(decisions.reserve) || decisions.reserve < 0) {
                    warn(`warn_reserve_value`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const as = document.getElementById(`askInput`);
                const de = document.getElementById(`defenseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (as) decisions.ask = as.value;
                if (de) decisions.defense = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        // Churn-adjusted LTV : CAC. LTV = (ARPU × margin) / churn.
        _ltvCac(ds) {
            if (!ds.cac || ds.cac <= 0 || ds.churn <= 0) return 0;
            const ltv = (ds.arpu * ds.margin) / ds.churn;
            return Math.round((ltv / ds.cac) * 100) / 100;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-round operating deltas. A "round" = one quarter (~3 months) of operating.
            const MONTHS = 3;
            let newFarmers = 0;        // gross new transacting farmers this round
            let acquisitionSpend = 0;  // S/ spent acquiring them
            let burnDelta = 0;         // change to monthly burn
            let arpuDelta = 0;         // change to ARPU (S/)
            let churnDelta = 0;        // change to monthly churn (absolute)
            let mrrBoostPct = 0;       // extra MRR lift from retention/quality (fractional)
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnosis round: cheap, sets the strategic posture. Small operating effect.
                const engine = d.focus / 100; // share of energy on activation/retention

                if (d.risk === `activation`) { churnDelta -= 0.01; mrrBoostPct += 0.04; coachKey = `coach_r1_activation`; }
                else if (d.risk === `registrations`) { churnDelta += 0.005; coachKey = `coach_r1_registrations`; }
                else if (d.risk === `brand`) { burnDelta += 6000; coachKey = `coach_r1_brand`; }
                else if (d.risk === `product`) { burnDelta += 4000; coachKey = `coach_r1_product`; }

                if (d.metric === `transacting`) { mrrBoostPct += 0.02; }
                else { coachKey = (coachKey === `coach_default`) ? `coach_r1_vanity` : coachKey; }

                if (d.diagnosis === `honest`) { /* clear-eyed; rewarded via survival below */ }
                else if (d.diagnosis === `optimistic`) { coachKey = `coach_r1_optimistic`; }
                else if (d.diagnosis === `deny`) { coachKey = `coach_r1_deny`; }

                // Energy on the engine lowers churn; energy on top-line adds a little reach but leaks.
                churnDelta -= 0.01 * engine;
                newFarmers += Math.round(40 + 60 * (1 - engine)); // chasing top-line adds more raw sign-ups
                acquisitionSpend += newFarmers * ds.cac;
                if (engine >= 0.5) { mrrBoostPct += 0.03; }

                const goodDiag = (d.risk === `activation` && d.metric === `transacting` && d.diagnosis === `honest`);
                summaryKey = goodDiag ? `sum_r1_good` : `sum_r1_weak`;
                if (goodDiag) coachKey = `coach_r1_sharp`;
            } else if (round === 2) {
                // ---- Market entry ----
                switch (d.market) {
                    case `ica`:
                        ds.focused = true;
                        newFarmers += 360; arpuDelta += 8; churnDelta -= 0.015;
                        ds.cac = Math.max(120, ds.cac - 40);
                        coachKey = `coach_r2_ica`;
                        break;
                    case `mantaro`:
                        ds.focused = true;
                        newFarmers += 460; churnDelta += 0.01; burnDelta += 14000; // logistics/trust cost
                        ds.cac = ds.cac + 50;
                        coachKey = `coach_r2_mantaro`;
                        break;
                    case `exporters`:
                        ds.focused = true;
                        newFarmers += 140; arpuDelta += 90; burnDelta += 8000; // big tickets, long cycle, few customers
                        coachKey = `coach_r2_exporters`;
                        break;
                    case `all`:
                        ds.spreadThin = true;
                        newFarmers += 175; churnDelta += 0.03; burnDelta += 34000; arpuDelta -= 10;
                        ds.cac = ds.cac + 80; // mediocre in three motions at once
                        coachKey = `coach_r2_spread`;
                        break;
                }

                // ---- Funding source ----
                switch (d.funding) {
                    case `equity`:
                        ds.cash += 220000; burnDelta += 4000; coachKey = (d.market === `all`) ? coachKey : `coach_r2_equity`;
                        break;
                    case `grant`:
                        ds.cash += 90000; // slow + partial this quarter; restrictive
                        break;
                    case `rbf`:
                        ds.tookDebt = true;
                        ds.cash += 180000; burnDelta += 22000; // serviced out of revenue at high burn
                        coachKey = `coach_r2_rbf`;
                        break;
                    case `strategic`:
                        ds.cash += 120000; newFarmers += 90; arpuDelta -= 12; // distribution, but channel dependence
                        break;
                }

                // ---- Two hires (sequence matters in a lending business) ----
                const hires = [d.hire1, d.hire2];
                if (hires.indexOf(`growth`) !== -1) { newFarmers += 330; burnDelta += 26000; ds.cac = ds.cac + 25; }
                if (hires.indexOf(`agronomists`) !== -1) { churnDelta -= 0.02; arpuDelta += 6; burnDelta += 12000; mrrBoostPct += 0.03; }
                if (hires.indexOf(`creditrisk`) !== -1) { ds.creditHired = true; burnDelta += 14000; }
                // Sequencing growth FIRST while skipping credit-risk = common error #4.
                if (d.hire1 === `growth` && hires.indexOf(`creditrisk`) === -1) { ds.growthFirst = true; coachKey = `coach_r2_growthfirst`; }

                acquisitionSpend += Math.round(newFarmers * ds.cac);

                const goodPlan = (d.market === `ica` || d.market === `mantaro` || d.market === `exporters`) &&
                                 (d.funding === `equity` || d.funding === `grant` || d.funding === `strategic`) &&
                                 (hires.indexOf(`creditrisk`) !== -1);
                summaryKey = d.market === `all` ? `sum_r2_spread` :
                             (ds.tookDebt ? `sum_r2_debt` :
                             (goodPlan ? `sum_r2_good` : `sum_r2_weak`));
                if (goodPlan && coachKey === `coach_default`) coachKey = `coach_r2_good`;
            } else if (round === 3) {
                // The off-season shock: repayments slow, a subsidised competitor enters.
                // Baseline damage from the shock.
                let shockChurn = 0.03;     // off-season + competitor pressure
                let badDebt = 60000;       // cash lost to slow/bad repayments before mitigation
                burnDelta += 0;            // burn changes set by the cuts below
                newFarmers += 150;         // baseline operating growth a surviving venture keeps making

                // ---- Re-cut burn ----
                switch (d.burn) {
                    case `surgical`:
                        burnDelta -= 30000; coachKey = `coach_r3_surgical`;
                        break;
                    case `deep`:
                        burnDelta -= 55000; newFarmers -= 120; churnDelta += 0.01; // froze the growth that makes you fundable
                        coachKey = `coach_r3_deep`;
                        break;
                    case `none`:
                        coachKey = `coach_r3_nocut`;
                        break;
                }

                // ---- Competitor response ----
                switch (d.competitor) {
                    case `retain`:
                        shockChurn -= 0.02; mrrBoostPct += 0.02; coachKey = (coachKey === `coach_default`) ? `coach_r3_retain` : coachKey;
                        break;
                    case `pricewar`:
                        ds.gamedMilestone = true;
                        arpuDelta -= 70; newFarmers += 150; coachKey = `coach_r3_pricewar`; // contribution-negative growth
                        break;
                    case `ignore`:
                        shockChurn += 0.02; newFarmers -= 60;
                        break;
                }

                // ---- Credit risk containment ----
                switch (d.credit) {
                    case `underwrite`:
                        badDebt = Math.round(badDebt * 0.35); coachKey = (coachKey === `coach_default`) ? `coach_r3_underwrite` : coachKey;
                        break;
                    case `freeze`:
                        badDebt = Math.round(badDebt * 0.20); newFarmers -= 90; mrrBoostPct -= 0.04; // safe but stalls activity
                        break;
                    case `ignore`:
                        badDebt = Math.round(badDebt * 1.6); // the lending book bites
                        if (!ds.creditHired) { badDebt = Math.round(badDebt * 1.3); coachKey = `coach_r3_creditbite`; }
                        break;
                }

                churnDelta += shockChurn;

                // ---- Reserve held against the shock ----
                ds.reserve = d.reserve * 1000; // option values are S/ thousands
                // A real reserve absorbs bad debt instead of the core runway taking the hit.
                const absorbed = Math.min(ds.reserve, badDebt);
                badDebt -= absorbed;
                ds.cash -= badDebt; // remaining bad debt hits cash directly this round

                const survivedWell = (d.burn === `surgical` && d.competitor === `retain` && d.credit === `underwrite` && d.reserve >= 40);
                summaryKey = d.competitor === `pricewar` ? `sum_r3_pricewar` :
                             (d.credit === `ignore` ? `sum_r3_creditbite` :
                             (survivedWell ? `sum_r3_good` : `sum_r3_weak`));
                if (survivedWell && coachKey === `coach_default`) coachKey = `coach_r3_good`;
            } else if (round === 4) {
                // The pitch round: mostly judged on the engine you built. Light operating effect.
                if (d.pitch === `engine`) { mrrBoostPct += 0.03; coachKey = `coach_r4_engine`; }
                else if (d.pitch === `vanity`) { coachKey = `coach_r4_vanity`; }
                else if (d.pitch === `milestone`) { coachKey = `coach_r4_milestone`; }

                if (d.ask === `rightsized`) { ds.cash += 150000; burnDelta += 3000; }
                else if (d.ask === `maxraise`) { ds.cash += 260000; burnDelta += 9000; coachKey = (coachKey === `coach_default`) ? `coach_r4_maxraise` : coachKey; }
                else if (d.ask === `nodilution`) { /* no capital — runway stays tight */ coachKey = (coachKey === `coach_default`) ? `coach_r4_nodilution` : coachKey; }

                if (d.defense === `factors`) { mrrBoostPct += 0.02; }
                else if (d.defense === `money`) { coachKey = (coachKey === `coach_default`) ? `coach_r4_money` : coachKey; }
                else if (d.defense === `luck`) { coachKey = (coachKey === `coach_default`) ? `coach_r4_luck` : coachKey; }

                // organic growth from the quarter as the engine compounds
                newFarmers += 260;
                acquisitionSpend += Math.round(newFarmers * ds.cac);

                const goodPitch = (d.pitch === `engine` && d.ask === `rightsized` && d.defense === `factors`);
                summaryKey = goodPitch ? `sum_r4_good` : `sum_r4_weak`;
                if (goodPitch) coachKey = `coach_r4_good`;
            }

            // ---- Apply the operating model ----
            // Acquisition spend is part of cash out this round (in addition to net burn).
            if (round === 2 || round === 4) {
                acquisitionSpend = Math.round((newFarmers > 0 ? newFarmers : 0) * ds.cac * 0.5);
            }

            // Update ARPU, churn, CAC (clamped to sane bounds).
            ds.arpu = Math.max(40, Math.round(ds.arpu + arpuDelta));
            ds.churn = Math.max(0.02, Math.min(0.25, Math.round((ds.churn + churnDelta) * 1000) / 1000));
            ds.burn = Math.max(20000, Math.round(ds.burn + burnDelta));

            // Net farmer change: gross new MINUS churned this round (churn is monthly, ~MONTHS months).
            const churnedOut = Math.round(ds.farmers * (1 - Math.pow(1 - ds.churn, MONTHS)));
            ds.farmers = Math.max(0, ds.farmers + Math.round(newFarmers) - churnedOut);

            // MRR is derived from transacting farmers × ARPU, plus retention/quality boosts.
            const baseMrr = ds.farmers * ds.arpu;
            ds.mrr = Math.max(0, Math.round(baseMrr * (1 + mrrBoostPct)));

            // Cash: subtract the quarter's net burn AND this round's acquisition spend.
            const netBurnQuarter = (ds.burn - ds.mrr) * MONTHS;
            ds.cash = Math.round(ds.cash - Math.max(0, netBurnQuarter) - Math.max(0, acquisitionSpend));
            if (ds.cash < 0) ds.cash = 0;

            // Runway = cash ÷ current net monthly burn (burn net of revenue).
            // When revenue covers burn the venture is self-sustaining: cap the displayed
            // runway at 36 months rather than report a meaningless cash/1 figure.
            const RUNWAY_CAP = 36;
            const netMonthly = ds.burn - ds.mrr;
            if (netMonthly <= 0) {
                ds.runway = ds.cash > 0 ? RUNWAY_CAP : 0;
            } else {
                ds.runway = Math.round((ds.cash / netMonthly) * 10) / 10;
                if (ds.runway > RUNWAY_CAP) ds.runway = RUNWAY_CAP;
            }

            // Churn-adjusted LTV:CAC.
            ds.ltvCac = this._ltvCac(ds);

            // ---- Survival probability: the composite the whole sim drives toward. ----
            ds.survival = this._survival(ds);

            ds.runwayHistory.push(ds.runway);
            ds.mrrHistory.push(ds.mrr);
            ds.farmersHistory.push(ds.farmers);
            ds.survivalHistory.push(ds.survival);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite (survival) where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                cash: ds.cash,
                runway: ds.runway,
                mrr: ds.mrr,
                farmers: ds.farmers,
                arpu: ds.arpu,
                churn: ds.churn,
                ltvCac: ds.ltvCac,
                survival: ds.survival,
                burn: ds.burn,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        // Survival probability (0–100): runway, traction vs the bar, unit-economics health,
        // and penalties for the classic errors.
        _survival(ds) {
            // Runway component: ~6 months is borderline; 12+ is comfortable.
            const runwayScore = Math.max(0, Math.min(1, ds.runway / 12));
            // Traction component: progress toward BOTH halves of the bar.
            const mrrScore = Math.max(0, Math.min(1, ds.mrr / this.BAR_MRR));
            const farmerScore = Math.max(0, Math.min(1, ds.farmers / this.BAR_FARMERS));
            const tractionScore = (mrrScore + farmerScore) / 2;
            // Unit-economics health: LTV:CAC, healthy at 3×.
            const unitScore = Math.max(0, Math.min(1, ds.ltvCac / 3));

            let s = (0.32 * runwayScore + 0.34 * tractionScore + 0.34 * unitScore) * 100;

            // Penalties for the COMMON ERRORS — wrong strategies measurably underperform.
            if (ds.tookDebt && ds.runway < 5) s -= 14;       // fast capital at high burn
            if (ds.spreadThin) s -= 12;                       // mediocre in three markets
            if (ds.growthFirst) s -= 10;                      // mis-sequenced hires in a lending business
            if (ds.gamedMilestone && ds.ltvCac < 3) s -= 12;  // gamed the milestone, money-losing engine
            if (ds.runway < 3) s -= 16;                       // about to run out of cash
            // Rewards for the survival path.
            if (ds.focused) s += 5;
            if (ds.creditHired) s += 5;

            return Math.max(2, Math.min(98, Math.round(s)));
        }

        _fmtPEN(v) {
            // S/ 1,234,567 with thousands separators.
            const n = Math.round(Number(v) || 0);
            return `S/ ` + n.toLocaleString(`en-US`);
        }

        _survivalLabel(v) {
            // Returns a one-decimal percentage; survival is already 0–100.
            return `${Math.round(v)}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.cosecha-card-runway`);
                if (card) {
                    card.classList.toggle(`cosecha-runway-danger`, n < 4);
                    card.classList.toggle(`cosecha-runway-good`, n >= 9);
                }
                return self._fmtMonths(n);
            });

            uiManager.bind(`mrrDisplay`, `domainState.mrr`, (v) => self._fmtPEN(v));
            uiManager.bind(`farmersDisplay`, `domainState.farmers`, (v) => Math.round(Number(v)).toLocaleString(`en-US`));

            uiManager.bind(`survivalDisplay`, `domainState.survival`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.cosecha-card-survival`);
                if (card) {
                    card.classList.toggle(`cosecha-survival-low`, n < 40);
                    card.classList.toggle(`cosecha-survival-mid`, n >= 40 && n < 65);
                    card.classList.toggle(`cosecha-survival-high`, n >= 65);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`unitDisplay`, `domainState.ltvCac`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.cosecha-unit-bar`);
                if (bar) {
                    bar.classList.toggle(`cosecha-unit-good`, n >= 3);
                    bar.classList.toggle(`cosecha-unit-mid`, n >= 1.5 && n < 3);
                }
                return self._fmtRatio(n);
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }
        }

        _fmtMonths(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _fmtRatio(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            if (!Number.isFinite(v) || v <= 0) return `—`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `×`;
        }

        getChartConfig() {
            return {
                ventureChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `MRR (% of S/ 150k bar)`,
                                data: [],
                                borderColor: `#3f7d3a`,
                                backgroundColor: `rgba(63,125,58,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#3f7d3a`,
                                yAxisID: `y`
                            },
                            {
                                label: `Transacting farmers (% of 1,000 bar)`,
                                data: [],
                                borderColor: `#2f6b6b`,
                                backgroundColor: `rgba(47,107,107,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6b6b`,
                                yAxisID: `y`
                            },
                            {
                                label: `Survival probability (%)`,
                                data: [],
                                borderColor: `#7d4fa0`,
                                backgroundColor: `rgba(125,79,160,0.08)`,
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7d4fa0`,
