                            },
                            {
                                label: `Runway (×10 months)`,
                                data: [],
                                borderColor: `#c2871f`,
                                backgroundColor: `rgba(194,135,31,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
