                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#9a8870` }, grid: { color: `rgba(92,58,30,0.06)` },
                                title: { display: true, text: `0–100 (indexed)`, color: `#9a8870` }
                            },
                            x: {
                                ticks: { color: `#9a8870` }, grid: { color: `rgba(92,58,30,0.04)` },
                                title: { display: true, text: `Quarter`, color: `#9a8870` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.mrrHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `Q` + i));
            const mrrPct = ds.mrrHistory.map((v) => Math.round(Math.min(120, (v / this.BAR_MRR) * 100)));
            const farmerPct = ds.farmersHistory.map((v) => Math.round(Math.min(120, (v / this.BAR_FARMERS) * 100)));
            const survival = ds.survivalHistory.map((v) => Math.round(v));
            const runwayScaled = ds.runwayHistory.map((v) => Math.round(Math.min(100, v * 10)));
            return {
                ventureChart: {
                    labels: labels,
                    datasets: [
                        { data: mrrPct },
                        { data: farmerPct },
                        { data: survival },
                        { data: runwayScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - the composite the whole sim drives toward is the survival score (0-100),
            // computed in calculateResults via _survival(ds); reported unchanged.
            return Math.round(ds.survival);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized investor-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="lp-cm-target ' + (ok ? 'lp-cm-met' : 'lp-cm-missed') + '">'
                    + '<span class="lp-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.hitBar, t('tgt_bar'))
                + chip(!!summary.healthyUnit, t('tgt_unit'))
                + chip(!!summary.alive, t('tgt_alive'))
                + chip(!!summary.cleanMilestone, t('tgt_clean'));
            const metric = function (label, val) {
                return '<div class="lp-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_mrr'), 'S/' + nz(summary.mrr))
                + metric(t('kpi_farmers'), nz(summary.farmers))
                + metric(t('kpi_ltvcac'), nz(summary.ltvCac) + 'x')
                + metric(t('kpi_runway'), nz(summary.runway) + 'm');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="lp-cm">'
                +   '<div class="lp-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="lp-cm-verdict">' + verdict + '</div>'
                +   '<div class="lp-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="lp-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="lp-cm-targets">' + targets + '</div>'
                +   '<div class="lp-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="lp-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const runway = Math.round(ds.runway * 10) / 10;
            const mrr = Math.round(ds.mrr);
            const farmers = Math.round(ds.farmers);
            const ltvCac = Math.round(ds.ltvCac * 10) / 10;
            const survival = Math.round(ds.survival);

            const hitMrr = mrr >= this.BAR_MRR;
            const hitFarmers = farmers >= this.BAR_FARMERS;
            const hitBar = hitMrr && hitFarmers;
            const healthyUnit = ltvCac >= 3;
            const alive = runway >= 3;

            // Outcome pattern. A margin-destroying price war (gamedMilestone) can never earn a
            // clean seed: even when a high-ticket market props the headline LTV:CAC up, discounting
            // fees to chase the count is the concept's anti-pattern #5 and is routed to Hollow Milestone.
            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_burned`;
            if (hitBar && healthyUnit && alive && survival >= 65 && !ds.gamedMilestone) perfKey = `grade_seed`;
            else if (ds.gamedMilestone && hitBar) perfKey = `grade_hollow`;
            else if (ds.tookDebt && runway < 4) perfKey = `grade_debt`;
            else if (ds.spreadThin && !hitBar) perfKey = `grade_spread`;
            else if (ds.growthFirst && !ds.creditHired) perfKey = `grade_lending`;
            else if (alive && survival >= 50) perfKey = `grade_standing`;
            else if (!alive) perfKey = `grade_runway`;
            const performance = t(perfKey);

            const insights = [];
            if (hitBar && healthyUnit && alive && !ds.gamedMilestone) insights.push(window.mySimulation.t(`insight_seed`));
            else if (ds.gamedMilestone && hitBar) insights.push(window.mySimulation.t(`insight_hollow`));
            else if (ds.tookDebt && runway < 4) insights.push(window.mySimulation.t(`insight_debt`));
            else if (ds.spreadThin) insights.push(window.mySimulation.t(`insight_spread`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.growthFirst && !ds.creditHired) insights.push(window.mySimulation.t(`insight_lending`));
            if (!healthyUnit) insights.push(window.mySimulation.t(`insight_unit_low`));
            if (!alive) insights.push(window.mySimulation.t(`insight_runway_low`));
            if (ds.focused && healthyUnit && alive) insights.push(window.mySimulation.t(`insight_focus`));
            if (hitFarmers && !hitMrr) insights.push(window.mySimulation.t(`insight_count_no_revenue`));

            return {
                gradeKey: perfKey,
                score: survival,
                cleanMilestone: !ds.gamedMilestone,
                runway: runway,
                mrr: mrr,
                farmers: farmers,
                ltvCac: ltvCac,
                survival: survival,
                hitMrr: hitMrr,
                hitFarmers: hitFarmers,
                hitBar: hitBar,
                healthyUnit: healthyUnit,
                alive: alive,
                performance: performance,
                composite: survival,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.runway < 3) return window.mySimulation.t(`hint_runway`);
            if (ds.tookDebt && ds.runway < 5) return window.mySimulation.t(`hint_debt`);
            if (ds.spreadThin && state.currentPeriod >= 2) return window.mySimulation.t(`hint_spread`);
            if (ds.growthFirst && !ds.creditHired) return window.mySimulation.t(`hint_lending`);
            if (ds.gamedMilestone && ds.ltvCac < 3) return window.mySimulation.t(`hint_hollow`);
            if (ds.ltvCac < 1.5) return window.mySimulation.t(`hint_unit`);
            if (ds.survival >= 65 && ds.runway >= 6) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Quarter`, i18nKey: `col_quarter` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.runway`, label: `Runway`, i18nKey: `col_runway`, formatter: (v) => self._fmtMonths(Number(v)) },
                { key: `results.mrr`, label: `MRR`, i18nKey: `col_mrr`, formatter: (v) => self._fmtPEN(v) },
                { key: `results.farmers`, label: `Farmers`, i18nKey: `col_farmers`, formatter: (v) => Math.round(Number(v)).toLocaleString(`en-US`) },
                { key: `results.survival`, label: `Survival`, i18nKey: `col_survival`, formatter: (v) => `${Math.round(Number(v))}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

